CREATE VIEW [DWC].[DimDateTime]
AS SELECT dt.[SKDate], dt.[DateKey], dt.[DateName], dt.[Year], dt.[YearName], dt.[MonthStartDate], dt.[MonthEndDate], dt.[MonthOfYear], dt.[MonthName], dt.[MonthNameShort], dt.[MonthNameNumeric], dt.[WeekOfYear], dt.[WeekOfYearName], dt.[WeekStartDate], dt.[WeekEndDate], dt.[WeekYear], dt.[WeekOfQuarter], dt.[WeekOfQuarterName], dt.[DayOfWeek], dt.[DayOfWeekName], dt.[DayOfMonth], dt.[DayOfQuarter], dt.[DayOfYear], dt.[QuarterStartDate], dt.[QuarterEndDate], dt.[QuarterOfYear], dt.[QuarterName], dt.[QuarterNameShort], dt.[FiscalQuarterNameShort], dt.[FiscalYear], dt.[HalfYearName], dt.[IsWorkday], dt.[IsWorkdayName], dt.[DayType], dt.[WeekType], dt.[MonthType], dt.[QuarterType], dt.[YearType], dt.[NASalesCurrentDay], dt.[NABusinessDay], dt.[NACumulativeBusinessDaysQTD], dt.[NACumulativeBusinessDaysYTD], dt.[NAQTDBdays], dt.[NAYTDBdays], dt.[NAHYTDBdays], dt.[NAWTDBdays], dt.[NACumulativeBusinessDaysWTD], dt.[AlignUSHoliday], dt.[AlignUSWorkingDay]
FROM [DW].[DimDateTime] dt;